# Mature ComfyUI REST/once-claim/resource-guard adapter; no model or sampling implementation.
import pathlib,json,time,subprocess,sys,socket,urllib.request,urllib.error,hashlib,uuid
import psutil
R=pathlib.Path(__file__).parent; F=json.loads((R/"freeze.json").read_text(encoding="utf-8"))
BASE="http://127.0.0.1:8197"; OWN=None; PID=None; LOG=None
def save(n,v): (R/n).write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding="utf-8")
def req(path,data=None,timeout=5):
    b=None if data is None else json.dumps(data).encode()
    q=urllib.request.Request(BASE+path,data=b,headers={"Content-Type":"application/json"})
    with urllib.request.urlopen(q,timeout=timeout) as r:
        s=r.read()
        return json.loads(s) if s else {}
def out(s): print(s,flush=True)
def gpu():
    try:
        a=subprocess.check_output(["nvidia-smi","--query-gpu=utilization.gpu,memory.used,temperature.gpu","--format=csv,noheader,nounits"],text=True,timeout=3).strip().split(",")
        return dict(zip(["gpu_util","gpu_mib","temperature"],map(float,a)))
    except Exception as e: return {"gpu_error":str(e)}
def reconcile_stop(reason):
    save("stop.json",{"reason":reason,"epoch":time.time(),"prompt_id":PID})
    try: req("/interrupt",{"prompt_id":PID})
    except Exception as e: out("INTERRUPT_RESPONSE "+str(e))
    until=time.monotonic()+30
    while time.monotonic()<until:
        try:
            q=req("/queue")
            if not q["queue_running"] and not q["queue_pending"]:
                save("stop-reconciled.json",{"queue":q,"epoch":time.time()});return
        except Exception: pass
        time.sleep(2)
    out("OWNED_SERVER_TERMINATION_REQUIRED")
try:
    assert psutil.virtual_memory().percent<80,"RESOURCE_ADMISSION_RAM80"
    assert time.time()-F["overall_started_epoch"]<1800,"OVERALL_BUDGET_EXPIRED"
    assert hashlib.sha256((R/"workflow.json").read_bytes()).hexdigest()==F["workflow_sha256"]
    w=json.loads((R/"workflow.json").read_text(encoding="utf-8"))
    with socket.socket() as s: assert s.connect_ex(("127.0.0.1",8197))!=0,"PORT_OCCUPIED_STOP"
    claim=R/"execution.claim"
    with claim.open("x",encoding="utf-8") as f: f.write(str(time.time()))
    LOG=(R/"service.log").open("x",encoding="utf-8")
    OWN=subprocess.Popen([sys.executable]+F["service_command"],cwd="C:/AI/MiniMax-H3/ComfyUI",stdout=LOG,stderr=subprocess.STDOUT)
    save("service.json",{"pid":OWN.pid,"command":[sys.executable]+F["service_command"],"epoch":time.time()})
    out("SERVICE "+str(OWN.pid))
    t0=time.monotonic()
    while True:
        assert OWN.poll() is None,"SERVICE_EXITED"
        try:
            info=req("/object_info",timeout=5)
            break
        except Exception:
            if time.time()-F["overall_started_epoch"]>1800:raise RuntimeError("QUALIFICATION_BUDGET_1800S")
            if psutil.virtual_memory().percent>=94:raise RuntimeError("RAM94_STARTUP")
            time.sleep(2)
    assert all(v["class_type"] in info for v in w.values()),"MISSING_NODE"
    for n,k in [("1","clip_name"),("2","unet_name"),("3","vae_name"),("4","vae_name"),("18","lora_name")]:
        typ=w[n]["class_type"]; schema=info[typ]["input"]
        spec=(schema.get("required",{})|schema.get("optional",{})).get(k)
        assert spec is not None,("INPUT_SCHEMA",typ,k)
        if isinstance(spec[0],list):assert w[n]["inputs"][k] in spec[0],("MODEL_NOT_REGISTERED",typ,k)
    q=req("/queue");assert not q["queue_running"] and not q["queue_pending"]
    save("G1-admission.json",{"status":"PASS_COMPATIBLE_CANDIDATE","startup_seconds":time.monotonic()-t0,"all_nodes_registered":True,"models_registered":True,"RAM":psutil.virtual_memory().percent,"gpu":gpu(),"quality":"NOT_YET_MEASURED","epoch":time.time()})
    out("G1_RUNTIME_PASS")
    PID=str(uuid.uuid4())
    save("submit-intent.json",{"prompt_id":PID,"epoch":time.time(),"workflow_sha256":F["workflow_sha256"]})
    start=time.monotonic()
    receipt=req("/prompt",{"prompt":w,"client_id":F["job"],"prompt_id":PID},timeout=15)
    save("receipt.json",receipt);PID=receipt["prompt_id"];out("SUBMITTED "+PID)
    pressure=None;history=None;aborted=None
    with (R/"telemetry.jsonl").open("x",encoding="utf-8") as tel:
        while True:
            dt=time.monotonic()-start
            h=req("/history/"+PID)
            if PID in h: history=h[PID];break
            m=psutil.virtual_memory();g=gpu()
            sample={"epoch":time.time(),"seconds":dt,"ram_percent":m.percent,**g}
            tel.write(json.dumps(sample)+"\n");tel.flush()
            if m.percent>=88 and g.get("gpu_util",100)<20:pressure=pressure or time.monotonic()
            else:pressure=None
            reason=None
            if m.percent>=94:reason="RAM94"
            elif pressure is not None and time.monotonic()-pressure>=30:reason="RAM88_LOWGPU30S"
            elif False:reason="NO_UNSUPPORTED_FIRST_STEP_TIMEOUT"
            elif time.time()-F["overall_started_epoch"]>=1800:reason="OVERALL_1800S"
            if reason:
                aborted=reason;reconcile_stop(reason)
                history=req("/history/"+PID).get(PID)
                break
            out("RUN "+str(round(dt,1))+"s RAM "+str(m.percent)+" GPU "+str(g))
            time.sleep(5)
    save("history.json",history)
    result={"prompt_id":PID,"generation_seconds":time.monotonic()-start,"aborted":aborted,"history_status":history.get("status") if history else None,"G3":"PENDING_VISUAL_REVIEW","FINAL_VALID":"NO"}
    if not history or history["status"]["status_str"]!="success" or aborted:
        result["G3"]="STOPPED";save("result.json",result);out(json.dumps(result))
    save("short-ready.json",{"epoch":time.time(),"candidate":result["candidate"],"status":"PENDING_REVIEW_SERVER_HELD"})
    while not (R/"release.request").exists():
        if psutil.virtual_memory().percent>=94 or time.time()-F["overall_started_epoch"]>=1800:
            reconcile_stop("HELD_SERVICE_RESOURCE_OR_TOTAL_BUDGET")
            break
        time.sleep(2);sys.exit(2)
    import av
    from PIL import Image,ImageDraw
    files=list((R/"output").glob("BLUE8-PAIRING-NATIVE-INT4-20261110*.mp4"));assert len(files)==1
    raw=files[0]
    with av.open(str(raw)) as c: frames=[f.to_image() for f in c.decode(video=0)]
    assert len(frames)==56 and frames[0].size==(608,832),("OUTPUT_SPEC",len(frames),frames[0].size)
    for idx in [0,11,22,33,44,55]: frames[idx].save(R/"evidence"/("frame-"+str(idx)+".png"))
    sheet=Image.new("RGB",(912,880),"white")
    for j,idx in enumerate([0,11,22,33,44,55]):
        sheet.paste(frames[idx].resize((304,416)),((j%3)*304,(j//3)*440));ImageDraw.Draw(sheet).text(((j%3)*304+4,(j//3)*440+420),str(idx),fill="black")
    sheet.save(R/"evidence"/"contact.jpg")
    FF="C:/Users/A/AppData/Local/Microsoft/WinGet/Packages/Gyan.FFmpeg_Microsoft.Winget.Source_8wekyb3d8bbwe/ffmpeg-8.1.1-full_build/bin/ffmpeg.exe"
    mux=R/"candidate-original-audio.mp4"
    subprocess.run([FF,"-v","error","-i",str(raw),"-i",str(R/"input/audio-short.wav"),"-map","0:v:0","-map","1:a:0","-c:v","copy","-c:a","aac","-shortest",str(mux)],check=True,timeout=20)
    result.update(raw=str(raw),candidate=str(mux),sha256=hashlib.sha256(mux.read_bytes()).hexdigest(),frames=len(frames),through_decode_seconds=time.monotonic()-start)
    save("result.json",result);out(json.dumps(result))
    save("short-ready.json",{"epoch":time.time(),"candidate":result["candidate"],"status":"PENDING_REVIEW_SERVER_HELD"})
    while not (R/"release.request").exists():
        if psutil.virtual_memory().percent>=94 or time.time()-F["overall_started_epoch"]>=1800:
            reconcile_stop("HELD_SERVICE_RESOURCE_OR_TOTAL_BUDGET")
            break
        time.sleep(2)
except Exception as e:
    save("runner-error.json",{"error":repr(e),"epoch":time.time(),"prompt_id":PID})
    if PID:
        try: reconcile_stop("RUNNER_ERROR:"+repr(e))
        except Exception: pass
    out("STOP "+repr(e));raise
finally:
    if OWN is not None:
        try: owned_children=psutil.Process(OWN.pid).children(recursive=True)
        except psutil.NoSuchProcess: owned_children=[]
        try: req("/free",{"unload_models":True,"free_memory":True})
        except Exception: pass
        for child in reversed(owned_children):
            try: child.terminate()
            except psutil.NoSuchProcess: pass
        _,alive=psutil.wait_procs(owned_children,timeout=10)
        for child in alive:
            try: child.kill()
            except psutil.NoSuchProcess: pass
        if OWN.poll() is None:
            OWN.terminate()
            try: OWN.wait(timeout=20)
            except subprocess.TimeoutExpired: OWN.kill();OWN.wait(timeout=5)
        save("shutdown.json",{"owned_pid":OWN.pid,"owned_children":[p.pid for p in owned_children],"exit":OWN.poll(),"epoch":time.time()})
    if LOG:LOG.close()

